// Replace with your own addresses, in lower case. Never commit real addresses to the repo.
const TEST_ADDRESSES = ['replace-with-your-test-address@example.com'];
const OWNER_ADDRESS = 'replace-with-the-owner-test-address@example.com';

const VERDICT_LABELS = {
  fit: 'Fits',
  fit_with_reservation: 'Fits with a reservation',
  not_fit: 'Does not fit',
};
const CONFIDENCE_LABELS = {
  high: 'identified',
  low: 'a likely guess',
  not_identified: 'not identified',
};
const FOOTER = 'WIZEROLL demo. This email was sent to a test address.';

const body = $input.first().json.body ?? {};
const record = body.record ?? {};
if (body.type !== 'INSERT' || body.table !== 'requests') return [];

const email = String(record.customer_email ?? '').trim().toLowerCase();
const log = Array.isArray(record.conversation_log) ? record.conversation_log : [];
const emails = [];

if (record.request_type === 'fit_check' && TEST_ADDRESSES.includes(email)) {
  const verdictEntry = [...log].reverse().find((entry) => entry.kind === 'verdict');
  const verdict = VERDICT_LABELS[record.verdict] ?? 'Your result';
  emails.push({
    to: email,
    subject: `WIZEROLL fit check: ${verdict}`,
    text: [
      'Hi,', '',
      `Here is your WIZEROLL fit check result: ${verdict}.`, '',
      String(verdictEntry?.text ?? ''), '',
      record.wants_order ? 'We noted that you want to order. Your request was passed to the business owner.' : '',
      '', FOOTER,
    ].join('\n'),
  });
}

// Only open service requests are sent. A request saved as solved needs no follow-up.
if (record.request_type === 'service' && record.status === 'pending') {
  if (TEST_ADDRESSES.includes(email)) {
    emails.push({
      to: email,
      subject: 'WIZEROLL service request received',
      text: ['Hi,', '', 'Your service request was passed to the business owner and is waiting to be handled.', '', FOOTER].join('\n'),
    });
  }
  const firstMessage = log.find((entry) => entry.role === 'customer')?.text ?? '';
  const conversation = log.map((entry) => `${entry.role === 'customer' ? 'Customer' : 'Advisor'}: ${entry.text}`).join('\n');
  emails.push({
    to: OWNER_ADDRESS,
    subject: 'WIZEROLL: new service request waiting',
    text: [
      'A new service request is waiting to be handled.', '',
      `Customer: ${email}`,
      `Fault: ${CONFIDENCE_LABELS[record.fault_match_confidence] ?? 'unknown'}`,
      `First message: ${firstMessage}`, '',
      'Conversation:', conversation, '',
      FOOTER,
    ].join('\n'),
  });
}

return emails.map((json) => ({ json }));
